css:
:scope{display:block;width:100%}.pw{background:#0F0E0C;color:#EDE6D8;font-family:var(--os-font-body)}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:88px 32px 96px;display:flex;flex-wrap:wrap;gap:72px;align-items:flex-start}
.pw__cv{flex:1 1 300px;display:flex;justify-content:center}
.pw__img{width:300px;max-width:100%;line-height:0;box-shadow:0 30px 60px rgba(0,0,0,.55)}.pw__img img{display:block;width:100%;height:auto}
.pw__ph{width:300px;height:450px;max-width:100%;box-sizing:border-box;border:1px solid #3A3531;box-shadow:0 30px 60px rgba(0,0,0,.55);display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:64px 20px 36px}
.pw__phw{font-family:var(--os-font-label);font-size:22px;letter-spacing:.32em}.pw__phs{font-family:var(--os-font-label);font-size:10px;letter-spacing:.3em;color:#C2B8A6}
.pw__tx{flex:999 1 520px;min-width:0}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:#C2B8A6}
.pw__rule{width:64px;height:2px;background:#8E4A30;margin:28px 0 32px}
.pw__h{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:72px;line-height:1.02}
.pw__lead{margin:24px 0 0;font-size:21px;line-height:1.5;max-width:32em}
.pw__fmt{margin-top:32px;border-top:1px solid #3A3531;padding-top:28px}.pw__lead+.pw__fmt{margin-top:48px}
.pw__row{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:12px}
.pw__fn{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:14px;letter-spacing:.3em;text-transform:uppercase;color:#EDE6D8}
.pw__fp{font-family:var(--os-font-label);font-size:13px;letter-spacing:.2em;text-transform:uppercase;color:#C2B8A6}
.pw__btns{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.2em;text-transform:uppercase;text-decoration:none;line-height:normal;color:#EDE6D8;border:1px solid #C2B8A6;padding:15px 21px}
.pw__btn--p{background:#8E4A30;border-color:#8E4A30;padding:16px 22px}
.pw__btn:focus-visible{outline:2px solid #EDE6D8;outline-offset:3px}
.pw__note{margin:14px 0 0;font-size:19px;line-height:1.5;color:#C2B8A6}
@media (max-width:767px){.pw__in{padding:48px 20px 56px;gap:40px}.pw__h{font-size:44px}.pw__lead{font-size:19px}.pw__kicker{font-size:11px}.pw__rule{margin:20px 0 24px}.pw__btns{flex-direction:column}.pw__btn{text-align:center}.pw__tx{flex-basis:100%}}
